  "把包含 SKILL.md 的目录放在下方路径。新对话会按名称和描述决定是否读取全文。在输入框输入 / 可以选择 Skill，也可以直接发送 /skill:名称。每个 Skill 都能单独停用；Vela 目录里的 Skill 还可以删除。": "把包含 SKILL.md 的目錄放在下方路徑。新對話會按名稱和描述決定是否讀取全文。在輸入框輸入 / 可以選擇 Skill，也可以直接發送 /skill:名稱。每個 Skill 都能單獨停用；Vela 目錄里的 Skill 還可以刪除。",
