  "工具折叠方式": "工具折疊方式",
  "「按 Assistant 消息」只合并同一条消息里的连续工具；「按位置关系」允许相邻消息的工具合并成一组，思考、正文、用户消息和交互卡片仍会打断分组。": "「按 Assistant 訊息」只合併同一條訊息里的連續工具；「按位置關係」允許相鄰訊息的工具合併成一組，思考、正文、使用者訊息和交互卡片仍會打斷分組。",
