  "开启后，紧凑模式的过程行显示每个工具调用与整轮的总耗时，并记住每条「展开 / 收起」状态，重开聊天后保持不变。耗时取自已有轨迹，缺少记录的旧会话不显示标签。": "開啓後，緊湊模式的過程行顯示每個工具呼叫與整輪的總耗時，並記住每條「展開 / 收起」狀態，重開聊天後保持不變。耗時取自已有軌跡，缺少記錄的舊會話不顯示標籤。",
