  "关注路径": "關注路徑",
  "在 {{workspace.name}} 修复以下问题：\n{{problem}}": "在 {{workspace.name}} 修復以下問題：\n{{problem}}",
  "1. 查阅工作区指令与相关实现，结合复现步骤 {{reproduction}} 和预期行为 {{expected}} 查明原因。关注路径：{{focus_path}}。\n2. 限定修复范围；无法复现时说明证据缺口，不猜测已验证。\n3. 实施必要改动。\n4. 按风险和影响范围验证，不默认运行全量测试。": "1. 查閱工作區指令與相關實現，結合復現步驟 {{reproduction}} 和預期行為 {{expected}} 查明原因。關注路徑：{{focus_path}}。\n2. 限定修復範圍；無法復現時說明證據缺口，不猜測已驗證。\n3. 實施必要改動。\n4. 按風險和影響範圍驗證，不預設執行全量測試。",
  "说明根因、改动、实际执行的验证与结果，以及剩余问题。": "說明根因、改動、實際執行的驗證與結果，以及剩餘問題。",
  "审查改动": "審查改動",
  "只读审阅未提交改动或两个明确 Git 提交之间的差异，不自动修复。": "只讀審閱未提交改動或兩個明確 Git 提交之間的差異，不自動修復。",
  "审查范围": "審查範圍",
