  "关注点": "關注點",
  "审查 {{workspace.name}} 的 {{scope}}。关注点：{{focus}}。": "審查 {{workspace.name}} 的 {{scope}}。關注點：{{focus}}。",
  "1. 按预览中保存的 Git 范围查阅差异与相关代码。双引用使用明确起止 SHA 比较，不使用 merge-base。未提交范围包含索引和工作区差异，并列出未跟踪文件与实际查看范围。\n2. 检查正确性和回归风险。\n3. 汇总发现，不修改文件、不自动修复；沿用 Plan 审阅机制。": "1. 按預覽中儲存的 Git 範圍查閱差異與相關程式碼。雙引用使用明確起止 SHA 比較，不使用 merge-base。未提交範圍包含索引和工作區差異，並列出未跟蹤檔案與實際查看範圍。\n2. 檢查正確性和回歸風險。\n3. 匯總發現，不修改檔案、不自動修復；沿用 Plan 審閱機制。",
  "按严重程度列出问题、文件位置、触发条件和建议。未发现问题时说明检查范围与限制。": "按嚴重程度列出問題、檔案位置、觸發條件和建議。未發現問題時說明檢查範圍與限制。",
