  "目标版本": "目標版本",
  "补充说明": "補充說明",
  "为 {{workspace.name}} 准备 {{version}} 的发布材料。补充说明：{{notes}}。": "為 {{workspace.name}} 準備 {{version}} 的發佈材料。補充說明：{{notes}}。",
  "1. 核对项目版本规则与保存的起止提交 SHA。使用两个明确提交比较，不自动改为 merge-base。\n2. 整理发布说明草稿。\n3. 列出需要的检查和发布步骤。本次仅准备材料，不创建 Tag、不推送、不发布。": "1. 核對專案版本規則與儲存的起止提交 SHA。使用兩個明確提交比較，不自動改為 merge-base。\n2. 整理髮布說明草稿。\n3. 列出需要的檢查和發佈步驟。本次僅準備材料，不建立 Tag、不推送、不發佈。",
