  "记忆正在被另一个进程写入{0}；若上次写入已中断，请确认后手动移除 {1}": "記憶正在被另一個處理程序寫入{0}；若上次寫入已中斷，請確認後手動移除 {1}",
  "无法获取记忆写入锁": "無法獲取記憶寫入鎖",
