  "The title is the version name or tag (for example v1.2.0). The body is Markdown release notes: group user-visible changes into short sections such as 新增 / 修复 / 改进 (or Features / Fixes / Improvements when writing in English). Summarize what changed for users instead of listing raw commit messages one by one, and skip merge commits. Discuss only commits and pull requests inside the supplied version range; never mention changes outside it. Keep human-written notes from the supplied manual notes, preserving their facts and intent, and keep the previous release's structure when one is supplied. Do not create tags or releases, do not claim a version was published, and do not invent dates, contributors or validation.": "The title is the version name or tag (for example v1.2.0). The body is Markdown release notes: group user-visible changes into short sections such as 新增 / 修復 / 改進 (or Features / Fixes / Improvements when writing in English). Summarize what changed for users instead of listing raw commit messages one by one, and skip merge commits. Discuss only commits and pull requests inside the supplied version range; never mention changes outside it. Keep human-written notes from the supplied manual notes, preserving their facts and intent, and keep the previous release's structure when one is supplied. Do not create tags or releases, do not claim a version was published, and do not invent dates, contributors or validation.",
